// Official mark: https://opencode.ai/brand
// Normalized to the same 15px visual height as Codex in a 20px viewBox.
// Inherit the foreground so the monochrome mark works in either theme.
export function OpenCodeIcon({ size = 16 }: { size?: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 20 20"
      fill="none"
      aria-hidden="true"
    >
      <path
        d="M13 14.5H7V8.5H13V14.5Z"
        fill="currentColor"
        fillOpacity="0.25"
      />
      <path
        d="M13 5.5H7V14.5H13V5.5ZM16 17.5H4V2.5H16V17.5Z"
        fill="currentColor"
        fillRule="evenodd"
        clipRule="evenodd"
      />
    </svg>
  );
}

// Official mark: https://pi.dev/logo-auto.svg
// Preserve the original geometry and colours, removing its large outer padding.
export function PiIcon({ size = 16 }: { size?: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 20 20"
      fill="none"
      aria-hidden="true"
    >
      <path d="M2.5 2.5H13.75V10H10V6.25H2.5V2.5Z" fill="#F09082" />
      <path d="M2.5 6.25H6.25V10H10V13.75H6.25V17.5H2.5V6.25Z" fill="#4D9ABF" />
      <path d="M13.75 10H17.5V17.5H13.75V10Z" fill="#F1BE58" />
    </svg>
  );
}

export function ProviderIcon({
  provider,
  size = 18,
}: {
  provider: Provider;
  size?: number;
}) {
  if (provider === "opencode") return <OpenCodeIcon size={size} />;
  if (provider === "pi") return <PiIcon size={size} />;
  return provider === "codex" ? (
    <CodexIcon size={size} />
  ) : (
    <ClaudeCodeIcon size={size} />
  );
}
